#include <U8g2lib.h>
#include <Wire.h>
#include <Servo.h>

U8G2_SH1106_128X64_NONAME_F_HW_I2C u8g2(U8G2_R0, U8X8_PIN_NONE);

// ---- servo config: pins 9 upward ----
const int NUM_SERVOS = 4;
const int SERVO_PINS[NUM_SERVOS] = {9, 10, 11, 12};
Servo servos[NUM_SERVOS];

int servoCount = 1;
int shotCount  = 10;
int level      = 1;

const int CLOSED = 0;
const int OPEN   = 90;

// ---- pins ----
const int ENC_A   = 2;
const int ENC_B   = 3;
const int ENC_PB  = 4;
const int CONFIRM = 5;

// ---- encoder state ----
int lastA = HIGH;

// ---- run state ----
enum Mode { SERVO_SELECT, SHOT_SELECT, MENU, COUNTDOWN, RUNNING };
Mode mode = SERVO_SELECT;

bool     isOpen[NUM_SERVOS]   = {false,false,false,false};
unsigned long phaseEnd[NUM_SERVOS] = {0,0,0,0};
int      curAngle[NUM_SERVOS] = {0,0,0,0};
unsigned long nextOpenAllowed = 0;
int      shotsDone = 0;

// ---- forward declarations ----
int  readEncoderDelta();
bool pressed();
void doServoSelect();
void doShotSelect();
void doMenu();
void doCountdown();
void doRunning();
void moveTo(int i, int target);
long stayOpenTime();
long gapTime();

void setup() {
  pinMode(ENC_A, INPUT_PULLUP);
  pinMode(ENC_B, INPUT_PULLUP);
  pinMode(ENC_PB, INPUT_PULLUP);
  pinMode(CONFIRM, INPUT_PULLUP);
  u8g2.begin();
  randomSeed(analogRead(A0));
  lastA = digitalRead(ENC_A);

  // attach EVERY servo right away and hold them all closed,
  // so none of them hunt/twitch from a missing signal at boot
  for (int i = 0; i < NUM_SERVOS; i++) {
    servos[i].attach(SERVO_PINS[i]);
    servos[i].write(CLOSED);
    curAngle[i] = CLOSED;
    isOpen[i] = false;
  }
}

void loop() {
  switch (mode) {
    case SERVO_SELECT: doServoSelect(); break;
    case SHOT_SELECT:  doShotSelect();  break;
    case MENU:         doMenu();        break;
    case COUNTDOWN:    doCountdown();   break;
    case RUNNING:      doRunning();     break;
  }
}

// ===== WHEEL: right = +1, left = -1 =====
int readEncoderDelta() {
  int a = digitalRead(ENC_A);
  int delta = 0;
  if (a != lastA && a == LOW) {
    delta = (digitalRead(ENC_B) != a) ? +1 : -1;
  }
  lastA = a;
  return delta;
}

bool pressed() {
  if (digitalRead(CONFIRM) == LOW || digitalRead(ENC_PB) == LOW) {
    delay(200);
    return true;
  }
  return false;
}

// ---------- STEP 1: how many servos ----------
void doServoSelect() {
  int d = readEncoderDelta();
  if (d != 0) {
    servoCount += d;
    if (servoCount < 1) servoCount = 1;
    if (servoCount > NUM_SERVOS) servoCount = NUM_SERVOS;
  }

  u8g2.clearBuffer();
  u8g2.drawBox(0, 0, 128, 14);
  u8g2.setDrawColor(0);
  u8g2.setFont(u8g2_font_6x12_tr);
  u8g2.drawStr(14, 11, "SERVOS PLUGGED?");
  u8g2.setDrawColor(1);
  u8g2.setFont(u8g2_font_logisoso28_tn);
  char buf[4]; sprintf(buf, "%d", servoCount);
  u8g2.drawStr(56, 52, buf);
  u8g2.setFont(u8g2_font_5x8_tr);
  u8g2.drawStr(6, 63, "turn=set  press=OK");
  u8g2.sendBuffer();

  if (pressed()) {
    mode = SHOT_SELECT;
  }
}

// ---------- STEP 2: how many shots ----------
void doShotSelect() {
  int d = readEncoderDelta();
  if (d != 0) {
    shotCount += d;
    if (shotCount < 1)  shotCount = 1;
    if (shotCount > 50) shotCount = 50;
  }

  u8g2.clearBuffer();
  u8g2.drawBox(0, 0, 128, 14);
  u8g2.setDrawColor(0);
  u8g2.setFont(u8g2_font_6x12_tr);
  u8g2.drawStr(34, 11, "HOW MANY");
  u8g2.setDrawColor(1);
  u8g2.setFont(u8g2_font_logisoso28_tn);
  char buf[4]; sprintf(buf, "%d", shotCount);
  int x = (shotCount >= 10) ? 44 : 56;
  u8g2.drawStr(x, 52, buf);
  u8g2.setFont(u8g2_font_5x8_tr);
  u8g2.drawStr(10, 63, "shots  press=OK");
  u8g2.sendBuffer();

  if (pressed()) mode = MENU;
}

// ---------- STEP 3: level ----------
void doMenu() {
  int d = readEncoderDelta();
  if (d != 0) {
    level += d;
    if (level < 1)  level = 1;
    if (level > 10) level = 10;
  }

  u8g2.clearBuffer();
  u8g2.drawBox(0, 0, 128, 14);
  u8g2.setDrawColor(0);
  u8g2.setFont(u8g2_font_6x12_tr);
  u8g2.drawStr(18, 11, "SELECT LEVEL");
  u8g2.setDrawColor(1);
  u8g2.setFont(u8g2_font_logisoso28_tn);
  char buf[4]; sprintf(buf, "%d", level);
  u8g2.drawStr(12, 50, buf);
  u8g2.drawFrame(50, 24, 70, 16);
  int fill = (level * 66) / 10;
  u8g2.drawBox(52, 26, fill, 12);
  u8g2.setFont(u8g2_font_5x8_tr);
  char info[24];
  sprintf(info, "%dsv %dsh  press=GO", servoCount, shotCount);
  u8g2.drawStr(2, 63, info);
  u8g2.sendBuffer();

  if (pressed()) mode = COUNTDOWN;
}

// ---------- COUNTDOWN ----------
void doCountdown() {
  for (int n = 5; n >= 1; n--) {
    u8g2.clearBuffer();
    u8g2.setFont(u8g2_font_6x12_tr);
    char lv[16]; sprintf(lv, "LEVEL %d", level);
    u8g2.drawStr(40, 12, lv);
    u8g2.setFont(u8g2_font_logisoso28_tn);
    char c[4]; sprintf(c, "%d", n);
    u8g2.drawStr(56, 52, c);
    u8g2.sendBuffer();
    delay(1000);
  }
  // align only the servos in play; the rest already sit closed from boot
  for (int i = 0; i < servoCount; i++) {
    moveTo(i, CLOSED);
    isOpen[i] = false;
    phaseEnd[i] = 0;
  }
  shotsDone = 0;
  nextOpenAllowed = millis();
  mode = RUNNING;
}

void moveTo(int i, int target) {
  servos[i].write(target);
  curAngle[i] = target;
}

// ---------- RUNNING (one target at a time) ----------
void doRunning() {
  u8g2.clearBuffer();
  u8g2.setFont(u8g2_font_6x12_tr);
  char lv[20]; sprintf(lv, "L%d  %d/%d", level, shotsDone, shotCount);
  u8g2.drawStr(28, 28, lv);
  u8g2.setFont(u8g2_font_5x8_tr);
  u8g2.drawStr(30, 48, "press = stop");
  u8g2.sendBuffer();

  unsigned long now = millis();

  // close the open target when its stay-time elapses
  for (int i = 0; i < servoCount; i++) {
    if (isOpen[i] && now >= phaseEnd[i]) {
      moveTo(i, CLOSED);
      isOpen[i] = false;
      nextOpenAllowed = millis() + gapTime();
    }
  }

  int openNow = 0;
  for (int i = 0; i < servoCount; i++) if (isOpen[i]) openNow++;

  // open one new random target -- ONLY if none are currently open
  if (shotsDone < shotCount && openNow == 0 && now >= nextOpenAllowed) {
    int closedList[NUM_SERVOS], n = 0;
    for (int i = 0; i < servoCount; i++) if (!isOpen[i]) closedList[n++] = i;
    if (n > 0) {
      int pick = closedList[random(0, n)];
      moveTo(pick, OPEN);
      isOpen[pick] = true;
      phaseEnd[pick] = millis() + stayOpenTime();
      shotsDone++;
    }
  }

  // round over
  if (shotsDone >= shotCount && openNow == 0) {
    for (int i = 0; i < servoCount; i++) { moveTo(i, CLOSED); isOpen[i] = false; }
    u8g2.clearBuffer();
    u8g2.setFont(u8g2_font_6x12_tr);
    u8g2.drawStr(40, 36, "DONE!");
    u8g2.sendBuffer();
    delay(1500);
    mode = MENU;
    return;
  }

  if (digitalRead(ENC_PB) == LOW) {
    delay(200);
    for (int i = 0; i < servoCount; i++) { moveTo(i, CLOSED); isOpen[i] = false; }
    mode = MENU;
  }
}

// =====================================================================
// ===============  LEVEL TIMING -- EDIT THESE YOURSELF  ===============
// =====================================================================
// All numbers in MILLISECONDS (1000 = 1 second).
// map(level, 1, 10, VALUE_AT_L1, VALUE_AT_L10) spreads evenly across levels.
//
//   LVL | stay open | gap before next
//    1  |  3.50 s   |  6.00 - 9.00 s
//    5  |  2.48 s   |  4.22 - 6.55 s
//   10  |  1.20 s   |  2.00 - 3.50 s

// --- STAY OPEN: how long a target holds at 90 before closing ---
long stayOpenTime() {
  return map(level, 1, 10, 3500, 1200);   // L1 = 3500ms, L10 = 1200ms
}

// --- GAP: random pause after a target closes before the next pops ---
long gapTime() {
  long lo = map(level, 1, 10, 6000, 2000);   // L1 min 6.0s -> L10 min 2.0s
  long hi = map(level, 1, 10, 9000, 3500);   // L1 max 9.0s -> L10 max 3.5s
  return random(lo, hi + 1);
}
